import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.B2ul6ABY.js";const u=JSON.parse('{"title":"Server & API","description":"","frontmatter":{},"headers":[],"relativePath":"design/server-api.md","filePath":"design/server-api.md"}'),n={name:"design/server-api.md"};function o(r,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="server-api" tabindex="-1">Server &amp; API <a class="header-anchor" href="#server-api" aria-label="Permalink to &quot;Server &amp; API&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/server-api.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><h2 id="http-server" tabindex="-1">HTTP Server <a class="header-anchor" href="#http-server" aria-label="Permalink to &quot;HTTP Server&quot;">​</a></h2><p>The server uses <strong>Fastify</strong> and binds to the configured host and port (see <code>configuration.md §Server</code>). It serves:</p><ul><li>REST API endpoints under <code>/api/*</code>.</li><li>WebSocket endpoint at <code>/ws</code>.</li><li>Static files for the Vue SPA from <code>web/dist/</code>.</li><li>Optional VitePress documentation at <code>/docs/</code>.</li></ul><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All <code>/api/*</code> endpoints require authentication:</p><ul><li><strong>Token source</strong>: <code>SAIVAGE_API_TOKEN</code> environment variable.</li><li><strong>Delivery</strong>: <code>Authorization: Bearer &lt;token&gt;</code> header or <code>?token=&lt;token&gt;</code> query parameter.</li><li><strong>Public</strong>: <code>/health</code> does not require authentication.</li><li><strong>WebSocket</strong>: Auth is checked on connection upgrade. Invalid auth → close with code <code>1008</code>.</li></ul><p>See <code>security.md</code> for details.</p><hr><h2 id="mutating-control-rules" tabindex="-1">Mutating control rules <a class="header-anchor" href="#mutating-control-rules" aria-label="Permalink to &quot;Mutating control rules&quot;">​</a></h2><p>Mutating REST endpoints participate in the same control plane as chat, CLI, web UI, and runtime helpers.</p><p>This means:</p><ul><li>each mutating route declares a safety class;</li><li>authz is evaluated against <code>(actor, surface=&#39;rest&#39;, safety_class)</code>;</li><li><code>preview_only</code> responses return previews plus preview hashes and do not mutate until explicitly confirmed;</li><li><code>deny</code> responses do not mutate;</li><li>every mutating call writes one control-action audit entry;</li><li>the route must call the canonical service rather than mutating runtime/card/note/process/config state ad hoc.</li></ul><p>Read-only routes skip authz/audit and rely on API auth plus redaction.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /health</span></span></code></pre></div><p>Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme-search&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;runtime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;idle&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>No authentication required.</p><h3 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/cards              List/filter cards</span></span>
<span class="line"><span>GET    /api/cards/:id          Get full card details</span></span>
<span class="line"><span>GET    /api/cards/:id/history  List card history entry headers</span></span>
<span class="line"><span>GET    /api/cards/:id/history/:seq   Get one full history entry</span></span>
<span class="line"><span>GET    /api/cards/:id/diff?from=&amp;to= Diff two versions</span></span>
<span class="line"><span>POST   /api/cards              Create a card</span></span>
<span class="line"><span>PATCH  /api/cards/:id          Update card fields</span></span>
<span class="line"><span>DELETE /api/cards/:id          Delete a card</span></span></code></pre></div><p>Card creation and updates via the API go through the same validation and canonical mutation path as the analyst.</p><p>Tracked card-field updates route through <code>CardStore.mutateCard</code> and produce history entries. Status/timing/result/metrics updates remain on the untracked path.</p><h3 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/state                      Runtime state + card index summary</span></span>
<span class="line"><span>POST   /api/runtime/pause              Pause runtime dispatch</span></span>
<span class="line"><span>POST   /api/runtime/resume             Resume runtime dispatch</span></span>
<span class="line"><span>POST   /api/runtime/freeze             Freeze runtime and write freeze manifest</span></span>
<span class="line"><span>POST   /api/runtime/resume-from-freeze Resume from freeze manifest</span></span></code></pre></div><p>Pause/resume/freeze routes use canonical runtime-control helpers and must stay in parity with analyst, CLI, and web UI behavior.</p><p>Generic resume from <code>frozen</code> is intentionally rejected; the operator must use <code>resume-from-freeze</code>.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/notifications</span></span>
<span class="line"><span>POST   /api/notifications/:id/acknowledge</span></span></code></pre></div><p>These endpoints operate on the <strong>operator-surface</strong> notification queue. Session-scoped acknowledgement for running agents uses the <code>acknowledge_notification</code> tool instead.</p><h3 id="control-actions-audit" tabindex="-1">Control actions audit <a class="header-anchor" href="#control-actions-audit" aria-label="Permalink to &quot;Control actions audit&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/control-actions?card_id=&amp;since=</span></span></code></pre></div><p>Returns recent control-action audit entries, optionally filtered. Use this to inspect preview-only rejections, authz denials, and mutation provenance across chat/REST/CLI/runtime/web UI.</p><h3 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/agents/:id/conversation    Get conversation snapshot for an agent session</span></span></code></pre></div><p>Returns the agent&#39;s recent conversation history (subject to context compaction — only the current window is available).</p><p>Synthetic operator-update injections may appear in this conversation history when pending notifications were delivered to the session.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/config             Get configuration (secrets redacted)</span></span>
<span class="line"><span>GET    /api/providers          List configured providers and their status</span></span></code></pre></div><p>Sensitive fields (<code>apiKey</code>, tokens) are replaced with redacted values in the response.</p><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/notes                   List all reconciled unacknowledged notes across cards</span></span>
<span class="line"><span>POST   /api/notes/:id/acknowledge   Mark a note as handled</span></span>
<span class="line"><span>DELETE /api/notes/:id               Delete an unhandled note</span></span>
<span class="line"><span>DELETE /api/notes                   Clear all unhandled notes</span></span></code></pre></div><p>Directive and escalation notes also trigger notifications. Notes queue reads are schema-validated and reconciled so ghost <code>note: undefined</code> rows should not be exposed.</p><h3 id="chat-sessions" tabindex="-1">Chat Sessions <a class="header-anchor" href="#chat-sessions" aria-label="Permalink to &quot;Chat Sessions&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/chats              List analyst chat sessions</span></span>
<span class="line"><span>GET    /api/chats/:sessionId   Get messages for a specific session</span></span>
<span class="line"><span>POST   /api/chats/:sessionId   Send a message to a chat session (as user)</span></span></code></pre></div><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/files?path=           List directory contents (project-relative path)</span></span>
<span class="line"><span>GET    /api/files/content?path=   Get file content (project-relative path)</span></span></code></pre></div><p>Security enforced:</p><ul><li>Path traversal (<code>..</code>, absolute paths outside project) → 403.</li><li>Sensitive files (<code>.saivage/auth-profiles.json</code>) → 403.</li><li>Files larger than 1 MB → 413.</li></ul><h3 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    /api/debug/state        Full runtime state dump</span></span>
<span class="line"><span>GET    /api/debug/errors       Recent errors and warnings</span></span>
<span class="line"><span>GET    /api/debug/timeline     Event timeline</span></span></code></pre></div><p>Debug endpoints expose internal state for troubleshooting. They are authenticated but not rate-limited (intended for operator use, not public exposure).</p><hr><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h2><h3 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ws://host:port/ws</span></span></code></pre></div><p>Auth is checked on upgrade. Invalid or missing auth → close <code>1008</code>.</p><h3 id="message-envelope" tabindex="-1">Message envelope <a class="header-anchor" href="#message-envelope" aria-label="Permalink to &quot;Message envelope&quot;">​</a></h3><p>All messages use a JSON envelope:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;message | activity | thinking | status | error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Direction</th><th>Content</th></tr></thead><tbody><tr><td><code>message</code></td><td>server → client</td><td>Chat message from an agent or system</td></tr><tr><td><code>activity</code></td><td>server → client</td><td>Agent activity update (tool call, progress)</td></tr><tr><td><code>thinking</code></td><td>server → client</td><td>Agent reasoning trace (if enabled)</td></tr><tr><td><code>status</code></td><td>server → client</td><td>Runtime status change</td></tr><tr><td><code>error</code></td><td>server → client</td><td>Error notification</td></tr><tr><td><code>message</code></td><td>client → server</td><td>User chat message to the analyst</td></tr><tr><td><code>card_history_appended</code></td><td>server → client</td><td>A tracked card mutation appended history</td></tr><tr><td><code>notification_added</code></td><td>server → client</td><td>Operator/session notification added</td></tr><tr><td><code>notification_acknowledged</code></td><td>server → client</td><td>Operator notification acknowledged</td></tr><tr><td><code>control_action_recorded</code></td><td>server → client</td><td>Mutating control action audited</td></tr></tbody></table><p>The web UI subscribes to all types and renders them in the appropriate panels (chat, activity feed, status bar, history and notification surfaces).</p><hr><h2 id="telegram-channel" tabindex="-1">Telegram Channel <a class="header-anchor" href="#telegram-channel" aria-label="Permalink to &quot;Telegram Channel&quot;">​</a></h2><p>The Telegram bot provides an alternative chat interface to the analyst.</p><h3 id="message-formatting" tabindex="-1">Message formatting <a class="header-anchor" href="#message-formatting" aria-label="Permalink to &quot;Message formatting&quot;">​</a></h3><p>Markdown from agent responses is converted to Telegram HTML:</p><table tabindex="0"><thead><tr><th>Markdown</th><th>HTML</th></tr></thead><tbody><tr><td><code>\`code\`</code></td><td><code>&lt;code&gt;code&lt;/code&gt;</code></td></tr><tr><td><code>\`\`\`block\`\`\`</code></td><td><code>&lt;pre&gt;block&lt;/pre&gt;</code></td></tr><tr><td><code>**bold**</code></td><td><code>&lt;b&gt;bold&lt;/b&gt;</code></td></tr><tr><td><code>*italic*</code></td><td><code>&lt;i&gt;italic&lt;/i&gt;</code></td></tr><tr><td><code>~~strike~~</code></td><td><code>&lt;s&gt;strike&lt;/s&gt;</code></td></tr><tr><td><code>\\[text\\](url)</code></td><td><code>&lt;a href=&quot;url&quot;&gt;text&lt;/a&gt;</code></td></tr><tr><td><code># Header</code></td><td><code>&lt;b&gt;Header&lt;/b&gt;</code></td></tr><tr><td><code>- item</code></td><td><code>• item</code></td></tr></tbody></table><h3 id="message-splitting" tabindex="-1">Message splitting <a class="header-anchor" href="#message-splitting" aria-label="Permalink to &quot;Message splitting&quot;">​</a></h3><p>Telegram enforces a 4096-character message limit. Long messages are split at paragraph boundaries. Each chunk is sent as a separate message with minimal delay between sends.</p><h3 id="session-management" tabindex="-1">Session management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session management&quot;">​</a></h3><ul><li>Each Telegram chat ID maps to a separate analyst session.</li><li>Sessions persist across bot restarts (chat logs are stored on disk).</li><li>Only user IDs in <code>allowedUserIds</code> can interact. Messages from other users are silently dropped.</li><li>Telegram authz defaults are stricter than web-chat for destructive and deployment-class actions.</li></ul><hr><h2 id="static-file-serving" tabindex="-1">Static File Serving <a class="header-anchor" href="#static-file-serving" aria-label="Permalink to &quot;Static File Serving&quot;">​</a></h2><p>The server serves the Vue SPA from <code>web/dist/</code>:</p><ul><li>All non-API, non-WebSocket requests that don&#39;t match a static file are rewritten to <code>index.html</code> (SPA routing).</li><li>If VitePress docs are built and available at <code>docs/.vitepress/dist/</code>, they are served under <code>/docs/</code>.</li></ul>`,81)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
